<?php $e=static fn(mixed $v):string=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8'); ?>
<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Community – MeldeVerkehr</title>
<style>body{font-family:system-ui,sans-serif;background:#f5f7fa;color:#172033;margin:0}main{max-width:1050px;margin:28px auto;padding:20px}.card{background:#fff;border:1px solid #dfe5ec;border-radius:15px;padding:20px;margin-bottom:14px}.nav a{margin-right:12px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(250px,1fr));gap:12px}.post{border:1px solid #e2e7ed;border-radius:12px;padding:16px}.muted{color:#66758a}.message,.error{padding:11px;border-radius:8px;margin:8px 0}.message{border:1px solid #8fb799}.error{border:1px solid #c99}textarea,input,select{width:100%;box-sizing:border-box;padding:10px;border:1px solid #bac5d1;border-radius:8px;font:inherit}button,.button{display:inline-block;padding:9px 13px;border:0;border-radius:9px;background:#172033;color:#fff;text-decoration:none;font-weight:700;margin-top:8px}</style></head><body><main>
<p class="nav"><a href="/dashboard">Dashboard</a><a href="/community/profile">Profil</a><a href="/community/network">Netzwerk</a><a href="/community/favorites">Favoriten</a><a href="/community/groups">Gruppen</a><a href="/community/problems">Problemstellen</a><a href="/community/messages">Nachrichten</a><a href="/community/appeals">Moderationsentscheidungen</a><a href="/community/leaderboard">Leaderboard</a></p>
<h1>Community</h1><?php if($message):?><div class="message"><?= $e($message) ?></div><?php endif;?><?php if($error):?><div class="error"><?= $e($error) ?></div><?php endif;?>
<?php if(!$profile):?><section class="card"><p>Für Beiträge benötigst du zuerst ein separates Community-Profil.</p><a class="button" href="/community/profile">Community-Profil anlegen</a></section>
<?php else:?><section class="card"><h2>Beitrag erstellen</h2><form method="post" action="/community/posts"><input type="hidden" name="_csrf" value="<?= $e($csrf) ?>"><label>Thema optional</label><input name="topic" maxlength="100"><label>Gruppe optional</label><select name="group_id"><option value="">Allgemein</option><?php foreach($groups as $g):?><?php if(!empty($g['joined'])):?><option value="<?= $e($g['id']) ?>"><?= $e($g['name']) ?></option><?php endif;?><?php endforeach;?></select><label>Beitrag</label><textarea name="body" rows="5" maxlength="10000" required></textarea><button type="submit">Veröffentlichen</button></form></section><?php endif;?>
<section class="card"><h2>Neueste Beiträge</h2><div class="grid"><?php foreach($posts as $p):?><article class="post"><p><a href="/community/u/<?= rawurlencode($p['username']) ?>"><strong>@<?= $e($p['username']) ?></strong></a><?php if($p['group_name']):?> · <?= $e($p['group_name']) ?><?php endif;?></p><?php if($p['topic']):?><strong><?= $e($p['topic']) ?></strong><?php endif;?><p><?= nl2br($e($p['body'])) ?></p><small class="muted"><?= $e($p['created_at']) ?> · <?= $e($p['comment_count']) ?> Kommentare · <?= $e($p['reaction_count']) ?> hilfreich</small><p><a href="/community/posts/<?= rawurlencode($p['id']) ?>">Öffnen</a></p><?php if(in_array((string)$p['id'],$favoriteIds,true)):?><form method="post" action="/community/posts/<?= rawurlencode($p['id']) ?>/unfavorite"><input type="hidden" name="_csrf" value="<?= $e($csrf) ?>"><button type="submit">★ Favorit entfernen</button></form><?php else:?><form method="post" action="/community/posts/<?= rawurlencode($p['id']) ?>/favorite"><input type="hidden" name="_csrf" value="<?= $e($csrf) ?>"><button type="submit">☆ Als Favorit speichern</button></form><?php endif;?></article><?php endforeach;?><?php if(!$posts):?><p class="muted">Noch keine Beiträge.</p><?php endif;?></div></section>
</main></body></html>